// Helper functions
export function getTranslatedMealTitle(dayNumber: number, mealType: string, lang: Language): string {
  const key = `${dayNumber}-${mealType}`;
  return mealTitleTranslations[key]?.[lang] || mealTitleTranslations[key]?.ru || '';
}

export function getTranslatedIngredients(dayNumber: number, mealType: string, lang: Language): string[] {
  const key = `${dayNumber}-${mealType}`;
  const data = ingredientTranslations[key];
  if (!data) return [];
  return data[lang] ?? data.ru ?? [];
}

export function getTranslatedSteps(dayNumber: number, mealType: string, lang: Language): string[] {
  const key = `${dayNumber}-${mealType}`;
  const data = stepTranslations[key];
  if (!data) return [];
  return data[lang] ?? data.ru ?? [];
}
